ALTER TABLE "campaign_expenses" DROP CONSTRAINT "campaign_expenses_fieldId_fkey";

-- DropForeignKey
ALTER TABLE "campaign_expenses" DROP CONSTRAINT "campaign_expenses_lotId_fkey";

-- DropForeignKey
ALTER TABLE "campaigns" DROP CONSTRAINT "campaigns_fieldId_fkey";

