ALTER TABLE "exit_fields" DROP CONSTRAINT "exit_fields_fieldId_fkey";

-- DropForeignKey
ALTER TABLE "exit_fields" DROP CONSTRAINT "exit_fields_lotId_fkey";

-- DropForeignKey
ALTER TABLE "field_lots" DROP CONSTRAINT "field_lots_fieldId_fkey";

-- DropForeignKey
ALTER TABLE "productive_unit_fields" DROP CONSTRAINT "productive_unit_fields_fieldId_fkey";

-- DropForeignKey
ALTER TABLE "productive_unit_fields" DROP CONSTRAINT "productive_unit_fields_lotId_fkey";

-- DropForeignKey
ALTER TABLE "stocks" DROP CONSTRAINT "stocks_fieldId_fkey";

-- DropForeignKey
ALTER TABLE "stocks" DROP CONSTRAINT "stocks_fieldLotId_fkey";

-- DropIndex
DROP INDEX "fields_uuid_key";

-- AlterTable
ALTER TABLE "campaigns" DROP COLUMN "fieldId",
DROP COLUMN "lotBranchId",
DROP COLUMN "lotBranchMode",
DROP COLUMN "lotBranchPromotedAt",
DROP COLUMN "lotBranchSourceCampaignId",
ADD COLUMN     "lotLayoutId" TEXT;

-- AlterTable
ALTER TABLE "fields" DROP COLUMN "geojson",
DROP COLUMN "uuid",
ADD COLUMN     "archivedAt" TIMESTAMP(3),
ADD COLUMN     "declaredHectares" DOUBLE PRECISION,
ADD COLUMN     "geometry" geometry(MultiPolygon,4326) NOT NULL,
ADD COLUMN     "hectares" DOUBLE PRECISION GENERATED ALWAYS AS (ST_Area("geometry"::geography) / 10000) STORED,
ADD COLUMN     "legacyId" TEXT,
ADD COLUMN     "legacyUuid" TEXT;

-- DropTable
DROP TABLE "field_lots";

-- DropEnum
DROP TYPE "LotBranchMode";

-- CreateTable
CREATE TABLE "lot_layouts" (
    "id" TEXT NOT NULL,
    "accountId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "sourceLayoutId" TEXT,
    "promotedAt" TIMESTAMP(3),
    "lockedAt" TIMESTAMP(3),
    "legacyBranchId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "lot_layouts_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "lots" (
    "id" TEXT NOT NULL,
    "fieldId" TEXT NOT NULL,
    "layoutId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "geometry" geometry(MultiPolygon,4326) NOT NULL,
    "hectares" DOUBLE PRECISION GENERATED ALWAYS AS (ST_Area("geometry"::geography) / 10000) STORED,
    "declaredHectares" DOUBLE PRECISION,
    "sourceLotId" TEXT,
    "archivedAt" TIMESTAMP(3),
    "legacyId" TEXT,
    "legacyUuid" TEXT,
    "legacyName" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "lots_pkey" PRIMARY KEY ("id")
);

