-- Geometry must be valid and non-empty (the API rejects invalid input with ST_IsValidReason;
-- the importer repairs it with ST_MakeValid). Prisma does not model CHECK constraints.
ALTER TABLE "fields" ADD CONSTRAINT "fields_geometry_valid" CHECK (ST_IsValid("geometry") AND NOT ST_IsEmpty("geometry"));
ALTER TABLE "lots" ADD CONSTRAINT "lots_geometry_valid" CHECK (ST_IsValid("geometry") AND NOT ST_IsEmpty("geometry"));

-- Lot name unique per field + layout among non-archived lots, case-insensitive
-- (partial expression index: not expressible in schema.prisma).
CREATE UNIQUE INDEX "lots_fieldId_layoutId_name_active_key" ON "lots"("fieldId", "layoutId", lower("name")) WHERE "archivedAt" IS NULL;
